    expect(res.stderr).toContain("non-compliant");
  });

  test("emits JSON and writes it to --output", async () => {
    const res = await runCli(
      [
        "--manifest",
        "fixtures/package.json",
        "--config",
        "fixtures/config.json",
        "--licenses",
        "fixtures/licenses.json",
        "--format",
        "json",
        "--output",
        "report.json",
      ],
